static Model ParseModel(const std::string& s){Check(s=="constant"||s=="variable","Use constant|variable");return s=="constant"?Model::Constant:Model::Variable;}
static const char* Name(Model m){return m==Model::Variable?"variable":"constant";}
static Window Select(const std::string& s){if(s=="smoke")return{"smoke",DtC,2.*DtC,DtC,3};if(s=="coarse")return{"coarse",DtC,End,Cadence,257};if(s=="half")return{"half",DtH,End,Cadence,257};throw std::runtime_error("Use smoke|coarse|half");}
static bool Ok(double x){return std::isfinite(x);}static bool Ok(float x){return std::isfinite(x);}static bool Ok(unsigned){return true;}static bool Ok(tdouble3 x){return Ok(x.x)&&Ok(x.y)&&Ok(x.z);}static bool Ok(tfloat3 x){return Ok(x.x)&&Ok(x.y)&&Ok(x.z);}
static double Dot(tdouble3 a,tdouble3 b){return a.x*b.x+a.y*b.y+a.z*b.z;}static double Norm(tdouble3 a){return std::sqrt(Dot(a,a));}static tdouble3 Vec(float3 a){return TDouble3(a.x,a.y,a.z);}static tdouble3 Abs(tdouble3 a){return TDouble3(fabs(a.x),fabs(a.y),fabs(a.z));}
static tdouble3 Product(const tmatrix3d& a,tdouble3 v){return TDouble3(a.a11*v.x+a.a12*v.y+a.a13*v.z,a.a21*v.x+a.a22*v.y+a.a23*v.z,a.a31*v.x+a.a32*v.y+a.a33*v.z);}
