template<class T>static bool Bits(const T& a,const T& b){return std::memcmp(&a,&b,sizeof(T))==0;}template<class T>static bool Same(const std::vector<T>& a,const std::vector<T>& b){return a.size()==b.size()&&(a.empty()||std::memcmp(a.data(),b.data(),a.size()*sizeof(T))==0);}
static void Cu(cudaError_t e){Check(e==cudaSuccess,cudaGetErrorString(e));}
template<class T>static std::vector<T> Down(const T* p,unsigned n){Check(p!=nullptr,"Required GPU state missing");std::vector<T> a(n);if(n)Cu(cudaMemcpy(a.data(),p,n*sizeof(T),cudaMemcpyDeviceToHost));return a;}template<class T>static void Up(T* p,const std::vector<T>& a){Check(p!=nullptr,"Required GPU upload missing");if(!a.empty())Cu(cudaMemcpy(p,a.data(),a.size()*sizeof(T),cudaMemcpyHostToDevice));}
