  hv("HydroMech",1);hv("PoreWaterRho",Rhow);hv("PoreWaterBulkModulus",Kw);hv("Porosity",N0);hv("HydraulicConductivity",.0001);hv("PoreDtSafety",.1);hv("PoreShepardRegularization",0);hv("PoreCompressionGradCorr",1);hv("PoreCompressionSourceMode",0);hv("HydroMechInitMode",0);hv("HydroMechTopLoadMode",0);hv("HydroMechDrainage",0);hv("HydroMechDynamicSeepage",0);hv("HydroMechConductivityModel",0);hv("HydroMechConductivityCk",0);
