    const fs::path out(cfg->DirOut);Fresh(out/"completion.json");Fresh(out/"endpoint_rates.csv");Fresh(out/"endpoint.csv");std::ofstream rates(out/"endpoint_rates.csv"),history(out/"endpoint.csv");rates<<std::setprecision(17);history<<std::setprecision(17);
    rates<<"part,time_s,saved_step,id,saved_theta,endpoint_theta,actual_rate,independent_rate,error,budget,error_over_budget,chain_reference,gradient_speed_reference,Gp_x,Gp_y,Gp_z,GJ_x,GJ_y,GJ_z,Ace_x,Ace_y,Ace_z,physical_a_x,physical_a_y,physical_a_z,conditional_qx,conditional_qy,conditional_qz,wrong_explicit_plus_g_rate,wrong_explicit_minus_g_rate,wrong_g_delta_rate,wrong_g_delta_over_original_budget\n";history<<"part,time_s,saved_step,source_signed_dterror,audit_fixed_error_before,audit_fixed_error_after,actual_slots,periodic_ghost_checks,max_rate_error_over_budget,actual_gradient_speed,independent_gradient_speed,actual_wave_scale_s,independent_wave_scale_s,actual_pore_scale_s,independent_pore_scale_s,necessary_bound_s,wrong_g_signal_over_original_budget,physical33_rollback_exact\n";
    std::vector<tdouble3> initial(Count);unsigned rows=0,ghosts=0,rollback=0,wrongWitnesses=0;double maxRatio=0,maxError=0,maxWrong=0,maxGradient=0;
